    r.panel('A');r.note('Measurement definition: reciprocal PAS within25nt, same P/M/S contributors, ≥80% mass in every state. Moved from a dedicated schematic to the caption.');bank=r.read('base:validation/narrative-v4-review/Figure4D-source-bank.tsv');q=bank[bank.tolerance.eq(25)&bank.axis.eq('rank')&((bank.design.eq('PMS')&bank.pair.eq('pair_mean'))|(bank.design.eq('PEM')&bank.pair.eq('H2_C')))];counts=q.groupby('design').n_genes.first().reindex(['PMS','PEM']);ax=r.ax(1,labels=['PMS','PEM'],kind='bar',pad=(10,6,2,8));ax.barh(range(2),counts,color=BLUE);ax.set(yticks=range(2),yticklabels=['PMS','PEM'],xlabel='Qualified genes');r.record('design-denominators',counts.to_frame());r.record('design-availability',r.read('same_pas/v2_primary_null_strata_audit.tsv'));r.note('PMS is the union across the two Xing pairs; pair_mean is an arithmetic mean, not a pooled correlation. PEM is the separate Liu × Guo2019–CIP control.')
