    r.record('PDLIM7-homolog-physical-sites',q);r.record('observed-state-sensitivity',r.read('axis:homolog_same_cohort_reference_comparison.tsv'));r.note('PDLIM7/Pdlim7 are the exact two homologous sites in Xing×CIP P–M; raw matched-site fractions preserve unassigned mass and are not renormalized here. No unrelated PAS or contributor estimator is substituted.')
